class ReportError(ValueError):
    """Error legible de validación; no se sustituyen datos erróneos por cero."""

def text(value: Any) -> str:
    return "" if value is None else str(value).strip()

def upper_plain(value: Any) -> str:
    return "".join(ch for ch in unicodedata.normalize("NFKD", text(value).upper())
                   if not unicodedata.combining(ch))

def code_key(value: Any) -> str:
    return re.sub(r"[^A-Z0-9]", "", upper_plain(value))

def desc_key(value: Any) -> str:
    return " ".join(re.findall(r"[A-Z0-9]+", upper_plain(value)))

def compare_desc(value: Any) -> str:
    s = desc_key(value)
    replacements = (
        ("SEGURIDADSINOTRUCK", "SECUNDARIO SINOTRUCK"),
        ("COMB SEPARADOR", "COMBUSTIBLE SEPARADOR"),
        ("COMP SEPARADOR", "COMBUSTIBLE SEPARADOR"),
        ("FILTRO DE ", "FILTRO "),
        ("FILTRO PARA ", "FILTRO "),
        ("FILTRO COMB ", "FILTRO COMBUSTIBLE "),
        ("AIRE DE SEGURIDAD", "AIRE SECUNDARIO"),
        ("FT FILTRO", "FILTRO"),
        ("USAR CON SERI ", "USAR CON SERIE "),
    )
    for a, b in replacements:
        s = s.replace(a, b)
    return s

def desc_similarity(a: Any, b: Any) -> float:
    a, b = compare_desc(a), compare_desc(b)
    return difflib.SequenceMatcher(None, a, b, autojunk=False).ratio()

def money(value: Any) -> Decimal:
    try:
        ans = Decimal(str(value))
    except (InvalidOperation, ValueError) as exc:
        raise ReportError(f"Número no válido: {value!r}") from exc
    if not ans.is_finite():
        raise ReportError("No se admiten valores infinitos ni NaN.")
    return ans

def number(value: Any) -> int | float:
    if isinstance(value, bool) or value is None:
        raise ReportError("Cantidad vacía o no numérica.")
    if isinstance(value, (int, float, Decimal)):
        d = money(value)
    else:
        s = text(value).replace("\u00a0", "").replace(" ", "")
        if re.fullmatch(r"-?\d{1,3}(?:\.\d{3})+,\d+", s):
            s = s.replace(".", "").replace(",", ".")
        elif re.fullmatch(r"-?\d{1,3}(?:,\d{3})+\.\d+", s):
            s = s.replace(",", "")
        elif "," in s and "." not in s:
            # En estos reportes de A2 la coma textual es separador decimal.
            s = s.replace(",", ".")
        d = money(s)
    return int(d) if d == d.to_integral_value() else float(d)

def valid_pack(pack: Any) -> bool:
    """Solo un empaque positivo y entero autoriza una cantidad en unidades."""
    try:
        if isinstance(pack, bool) or pack is None or text(pack) == "":
            return False
        p = money(pack)
        return p > 0 and p == p.to_integral_value()
    except (ReportError, TypeError):
        return False


def quantity_for_pack(quantity: Any, pack: Any) -> int:
    """Menor múltiplo entero >= necesidad, sin redondear hacia abajo.

    Usa una fracción exacta de Decimal: evita errores de división binaria.
    Cero sigue siendo cero. Un empaque desconocido NUNCA se convierte en 1.
    """
    if isinstance(quantity, bool) or quantity is None:
        raise ReportError("La necesidad debe ser un número no negativo.")
    q = money(quantity)
    if q < 0:
        raise ReportError("No se puede ajustar una necesidad negativa.")
    if not valid_pack(pack):
        raise ReportError("Falta un empaque entero positivo confirmado en el catálogo.")
    p = int(money(pack))
    numerator, denominator = q.as_integer_ratio()
    divisor = denominator * p
    return ((numerator + divisor - 1) // divisor) * p


def column_index(ref: str) -> int:
    col = re.match(r"[A-Z]+", ref)
    if not col:
        return 0
    result = 0
    for c in col.group():
        result = result * 26 + ord(c) - 64
    return result

def column_name(n: int) -> str:
    ans = ""
    while n:
        n, r = divmod(n - 1, 26)
        ans = chr(65 + r) + ans
    return ans

def xml_root(data: bytes) -> ET.Element:
    if b"<!DOCTYPE" in data or b"<!ENTITY" in data:
        raise ReportError("XML con entidades no admitidas.")
    try:
        return ET.fromstring(data)
    except ET.ParseError as exc:
        raise ReportError("El archivo contiene XML no válido.") from exc

@dataclass
class Sheet:
    name: str
    part: str
    state: str
    rows: dict[int, dict[int, Any]]
    formulas: dict[str, str]
    raw: bytes
    styles: dict[str, str] = field(default_factory=dict)

def xlsx_parts(data: bytes) -> dict[str, bytes]:
    if len(data) > MAX_INPUT:
        raise ReportError("El archivo supera el límite de 25 MB.")
    try:
        with ZipFile(io.BytesIO(data)) as z:
            infos = z.infolist()
            if len(infos) > 10000 or sum(i.file_size for i in infos) > MAX_EXPANDED:
                raise ReportError("Archivo demasiado grande al descomprimir.")
            if len({i.filename for i in infos}) != len(infos):
                raise ReportError("El XLSX contiene partes duplicadas.")
            if any(i.flag_bits & 1 for i in infos):
                raise ReportError("No se admiten archivos cifrados.")
            if "xl/workbook.xml" not in z.namelist():
                raise ReportError("No es un libro XLSX válido.")
            return {i.filename: z.read(i) for i in infos}
    except BadZipFile as exc:
        raise ReportError("Usa un archivo .xlsx real, no un .xls renombrado.") from exc

def read_book(data: bytes) -> tuple[dict[str, bytes], list[Sheet]]:
    parts = xlsx_parts(data)
    shared = []
    if "xl/sharedStrings.xml" in parts:
        for si in xml_root(parts["xl/sharedStrings.xml"]):
            ts = [t.text or "" for t in si.findall(".//m:t", NS)]
            shared.append("".join(ts))
    if "xl/_rels/workbook.xml.rels" not in parts:
        raise ReportError("Faltan las relaciones de las hojas del libro XLSX.")
    rels = {
        r.get("Id"): r.get("Target")
        for r in xml_root(parts["xl/_rels/workbook.xml.rels"])
        if r.get("TargetMode") != "External"
    }
    sheets = []
    n_cells = 0
    for meta in xml_root(parts["xl/workbook.xml"]).findall("m:sheets/m:sheet", NS):
        target = rels.get(meta.get("{" + NS_REL + "}id"))
        if not target:
            raise ReportError("No se encuentra una hoja del libro.")
        part = target.lstrip("/") if target.startswith("/") else posixpath.normpath("xl/" + target)
        if part not in parts:
            raise ReportError("Referencia de hoja no válida.")
        raw = parts[part]
        root = xml_root(raw)
        rows, forms, styles = {}, {}, {}
        for row in root.findall("m:sheetData/m:row", NS):
            try:
                rnum = int(row.get("r", "0"))
            except ValueError as exc:
                raise ReportError("El archivo contiene un número de fila no válido.") from exc
            if rnum < 1 or rnum > 1048576 or rnum in rows:
                raise ReportError("El archivo contiene filas repetidas o fuera del rango de Excel.")
            vals = {}
            seen_columns = set()
            row_has_formula = False
            for cell in row:
                n_cells += 1
                if n_cells > 500000:
                    raise ReportError("El libro supera 500.000 celdas.")
                ref = cell.get("r", "")
                cnum = column_index(ref)
                if (not re.fullmatch(r"[A-Z]+[1-9][0-9]*", ref)
                        or int(re.sub(r"[A-Z]+", "", ref)) != rnum
                        or cnum < 1 or cnum > 16384 or cnum in seen_columns):
                    raise ReportError(f"La hoja {meta.get('name', '')} contiene una referencia de celda repetida o inválida: {ref}.")
                seen_columns.add(cnum)
                styles[ref] = cell.get("s", "")
                v = cell.find("m:v", NS)
                val = v.text if v is not None else None
                typ = cell.get("t")
                f = cell.find("m:f", NS)
                if f is not None:
                    row_has_formula = True
                    forms[ref] = f.text or ""
                if typ == "s" and val is not None:
                    try:
                        ix = int(val)
                        if ix < 0:
                            raise ValueError()
                        val = shared[ix]
                    except (IndexError, ValueError) as exc:
                        raise ReportError("Texto compartido no válido.") from exc
                elif typ == "inlineStr":
                    val = "".join(t.text or "" for t in cell.findall(".//m:t", NS))
                elif typ == "b" and val is not None:
                    val = val == "1"
                elif typ == "e":
                    val = "#ERROR_EXCEL:" + text(val)
                elif typ not in ("str", "s", "inlineStr") and val is not None:
                    try:
                        d = Decimal(val)
                        if not d.is_finite():
                            raise ReportError(f"{meta.get('name', '')}, {ref}: número no finito.")
                        val = int(d) if d == d.to_integral_value() else float(d)
                    except InvalidOperation:
                        pass
                if val is not None:
                    vals[cnum] = val
            if vals or row_has_formula:
                rows[rnum] = vals
        sheets.append(Sheet(meta.get("name", ""), part, meta.get("state", "visible"),
                            rows, forms, raw, styles))
    return parts, sheets

@dataclass(frozen=True)
class Product:
    code: str
    description: str
    pack: int | float
    price: int | float
    catalog_sheet: str
    catalog_row: int

@dataclass(frozen=True)
class SourceRow:
    sheet: str
    row: int
    code: str
    description: str
    quantity: int | float

    @property
    def key(self) -> str:
        return hashlib.sha256(
            (code_key(self.code) + "\n" + desc_key(self.description)).encode("utf-8")
        ).hexdigest()

@dataclass
class Match:
    source: SourceRow
    product: Product | None
    method: str
    warnings: list[str] = field(default_factory=list)
    critical: list[str] = field(default_factory=list)
    suggestions: list[str] = field(default_factory=list)
    approved: bool = False
    indexed: bool = False

    @property
    def output_code(self) -> str:
        return self.product.code if self.product else self.source.code

    @property
    def output_description(self) -> str:
        return self.product.description if self.product else self.source.description

    @property
    def needs_review(self) -> bool:
        return bool(self.critical)

    @property
    def pack_issue(self) -> bool:
        """Discrepancia del ORIGEN; el ajuste se aplica solo a la salida."""
        if not self.product or not valid_pack(self.product.pack):
            return False
        return money(self.source.quantity) != money(self.output_quantity)

    @property
    def output_quantity(self) -> int | float:
        if not self.product or not valid_pack(self.product.pack):
            return self.source.quantity
        return quantity_for_pack(self.source.quantity, self.product.pack)

    @property
    def added_units(self) -> Decimal:
        return money(self.output_quantity) - money(self.source.quantity)

    @property
    def load_reasons(self) -> list[str]:
        """Bloqueos de carga: una aprobación de identidad no los puede ocultar."""
        reasons = list(self.critical)
        if not self.product:
            reasons.append("SIN_PRODUCTO_NI_EMPAQUE_VALIDADO")
        elif not valid_pack(self.product.pack):
            reasons.append("EMPAQUE_AUSENTE_O_NO_ENTERO_POSITIVO")
        if money(self.output_quantity) <= 0:
            reasons.append("CANTIDAD_CERO_NO_SE_ENVIA_AL_PROVEEDOR")
        if self.product:
            try:
                if money(self.product.price) < 0:
                    reasons.append("PRECIO_INVALIDO")
            except ReportError:
                reasons.append("PRECIO_INVALIDO")
        return list(dict.fromkeys(reasons))

    @property
    def loadable(self) -> bool:
        return not self.load_reasons


@dataclass
class Template:
    data: bytes
    parts: dict[str, bytes]
    sheets: list[Sheet]
    main: Sheet
    catalog: list[Product]
    by_code: dict[str, list[Product]]
    by_desc: dict[str, list[Product]]

@lru_cache(maxsize=3)
def load_template(data: bytes) -> Template:
    parts, sheets = read_book(data)
    mains = [s for s in sheets if [
        desc_key(s.rows.get(1, {}).get(c)) for c in range(1, 7)
    ] == ["CODIGO", "DESCRIPCION", "UD EMP", "CANTIDAD", "PRECIO UND", "TOTAL"]]
    if len(mains) > 1:
        raise ReportError("La plantilla contiene varias hojas de pedido. Conserva una sola para evitar una exportación ambigua.")
    main = mains[0] if mains else None
    if main is None:
        raise ReportError("La plantilla debe conservar Codigo, Descripción, Ud.Emp, Cantidad, Precio Und y Total.")
    if main.state != "visible":
        raise ReportError("La hoja del pedido WEB debe estar visible.")
    cat = next((s for s in sheets if s.name == "DatosValidacion"), None)
    if cat is None:
        raise ReportError("La plantilla no contiene la hoja DatosValidacion.")
    products = []
    for r, v in cat.rows.items():
        if not any(text(v.get(c)) for c in (1, 2, 3, 4)):
            continue
        if not text(v.get(1)) or not text(v.get(2)):
            raise ReportError(f"Catálogo, fila {r}: falta código o descripción. No se ha omitido el producto.")
        if not code_key(v.get(1)):
            raise ReportError(f"Catálogo, fila {r}: código no válido.")
        for c in (1, 2, 3, 4):
            val = v.get(c)
            if isinstance(val, str) and val.startswith("#ERROR_EXCEL"):
                raise ReportError(f"Catálogo, fila {r}: la celda {column_name(c)} contiene un error de Excel.")
        try:
            pack, price = number(v.get(3)), number(v.get(4))
        except ReportError as exc:
            raise ReportError(f"Catálogo, fila {r}: empaque o precio no válido.") from exc
        if not valid_pack(pack) or price < 0:
            raise ReportError(f"Catálogo, fila {r}: el empaque debe ser entero positivo y el precio no negativo. No se asume empaque 1.")
        products.append(Product(text(v[1]), text(v[2]), pack, price, cat.name, r))
    if not products:
        raise ReportError("El catálogo de la plantilla está vacío.")
    bc, bd = collections.defaultdict(list), collections.defaultdict(list)
    for p in products:
        bc[code_key(p.code)].append(p)
        bd[desc_key(p.description)].append(p)
    if any(len(v) > 1 for v in bc.values()):
        raise ReportError("La plantilla contiene códigos duplicados o indistinguibles al normalizarlos.")
    return Template(data, parts, sheets, main, products, dict(bc), dict(bd))

def embedded_template() -> bytes:
    data = base64.b64decode(TEMPLATE_B64)
    if hashlib.sha256(data).hexdigest() != TEMPLATE_SHA256:
        raise ReportError("La copia incluida de FORMATO WEB no supera la validación.")
    return data

HEADER_CODE = {"CODIGO", "COD", "REFERENCIA", "CODIGO PRODUCTO"}
HEADER_DESC = {"DESCRIPCION", "DESCRIPCION PRODUCTO", "PRODUCTO"}
HEADER_QTY = {"A PEDIR", "APEDIR", "CANTIDAD A PEDIR", "REPOSICION", "CANTIDAD"}

def find_header(vals: dict[int, Any]) -> tuple[int, int, int] | None:
    lookup = {c: desc_key(v) for c, v in vals.items()}
    c = next((i for i, t in lookup.items() if t in HEADER_CODE), None)
    d = next((i for i, t in lookup.items() if t in HEADER_DESC), None)
    q = next((i for label in ("A PEDIR", "APEDIR", "CANTIDAD A PEDIR", "REPOSICION", "CANTIDAD") for i, t in lookup.items() if t == label), None)
    if c and d and q:
        for label, labels in (("código", HEADER_CODE), ("descripción", HEADER_DESC)):
            if sum(t in labels for t in lookup.values()) > 1:
                raise ReportError(f"Encabezado ambiguo: hay más de una columna de {label}.")
        if sum(t == lookup[q] for t in lookup.values()) > 1:
            raise ReportError("Encabezado ambiguo: hay más de una columna de cantidad con el mismo nombre.")
        return c, d, q
    return None

@lru_cache(maxsize=3)
def read_replenishment(data: bytes) -> tuple[list[SourceRow], list[str]]:
    _, sheets = read_book(data)
    records, notes = [], []
    formula_quantities = 0
    total_headers = 0
    for sh in sheets:
        if sh.state in ("hidden", "veryHidden"):
            continue
        first = [desc_key(sh.rows.get(1, {}).get(c)) for c in range(1, 7)]
        if first == ["CODIGO", "DESCRIPCION", "UD EMP", "CANTIDAD", "PRECIO UND", "TOTAL"]:
            raise ReportError("Has cargado un FORMATO WEB de salida como reposición. "
                              "Carga el reporte ORIGINAL con Código, Descripción y A pedir; "
                              "reutilizar la salida ocultaría discrepancias ya reemplazadas.")
        header = None
        found_this_sheet = False
        for r, vals in sorted(sh.rows.items()):
            try:
                new_header = find_header(vals)
            except ReportError as exc:
                raise ReportError(f"{sh.name}, fila {r}: {exc}") from exc
            if new_header:
                header = new_header
                total_headers += 1
                found_this_sheet = True
                continue
            if not header:
                continue
            cc, dc, qc = header
            code, desc, qty = text(vals.get(cc)), text(vals.get(dc)), vals.get(qc)
            for label, col in (("código", cc), ("descripción", dc), ("cantidad", qc)):
                ref = f"{column_name(col)}{r}"
                value = vals.get(col)
                if ref in sh.formulas and value in (None, ""):
                    raise ReportError(f"{sh.name}, {ref}: la fórmula de {label} no tiene un resultado guardado. Abre el reporte en Excel, recalcula y guárdalo como .xlsx.")
                if isinstance(value, str) and value.startswith("#ERROR_EXCEL"):
                    raise ReportError(f"{sh.name}, {ref}: hay un error de Excel en {label}. Corrige la fórmula antes de procesar.")
            if not code and not desc and qty in (None, ""):
                continue
            line = desc_key(" ".join(text(v) for v in vals.values()))
            labels = ("TOTAL", "TOTAL GENERAL", "SUBTOTAL", "SUB TOTAL")
            is_footer = (desc_key(code) in labels and not desc) or (desc_key(desc) in labels and not code)
            is_footer = is_footer or (not desc and line.startswith(("PAGINA ", "FECHA ", "DEPARTAMENTO ")))
            if is_footer:
                continue
            if qty in (None, ""):
                if code or desc:
                    raise ReportError(f"{sh.name}, fila {r}: falta la cantidad. No se ha omitido ni convertido a cero.")
                continue
            if not code and not desc:
                raise ReportError(f"{sh.name}, fila {r}: hay cantidad sin código ni descripción. Identifica el producto o marca la fila como TOTAL.")
            try:
                quantity = number(qty)
            except ReportError as exc:
                raise ReportError(f"{sh.name}, fila {r}: cantidad no válida {qty!r}.") from exc
            if quantity < 0:
                raise ReportError(f"{sh.name}, fila {r}: cantidad negativa; corrígela antes de generar el pedido.")
            if f"{column_name(qc)}{r}" in sh.formulas:
                formula_quantities += 1
            records.append(SourceRow(sh.name, r, code, desc, quantity))
        if not found_this_sheet:
            notes.append(f"Hoja {sh.name}: no contiene un encabezado de reposición y no se ha procesado.")
    if total_headers == 0:
        raise ReportError("No se detectaron columnas Código, Descripción y A pedir.")
    if not records:
        raise ReportError("No se encontraron productos después del encabezado.")
    if len(records) > 20000:
        raise ReportError("El reporte supera 20.000 productos.")
    if formula_quantities:
        notes.append(f"{formula_quantities} cantidades provienen de fórmulas. Se usó el resultado guardado en el Excel; guarda el archivo después de recalcular cuando cambien sus datos.")
    zero_count = sum(r.quantity == 0 for r in records)
    if zero_count:
        notes.append(f"{zero_count} productos tienen cantidad cero: permanecen en la revisión y se excluyen del archivo para cargar.")
    return records, notes

