def _ui_settings(st, memory: LocalMemory, decisions: dict, template: Template | None, template_name: str = "") -> None:
    def clear_result_cache():
        # Invalida resultados en pantalla; nunca borra la memoria ni el historial.
        for key in list(st.session_state):
            if key.startswith(("web_process_", "web_valid_", "web_review_", "supplement_pack_", "supplement_manual_", "supplement_price_")):
                st.session_state.pop(key, None)

    if template is not None:
        with st.expander("Consultar catálogos · Salida WEB e Inventario A2", key="catalogs_expander"):
            st.caption(f"Formato base: {template_name} · {_ui_format(len(template.catalog))} referencias disponibles para la salida")
            render_catalog(st, template, memory)
    with st.expander("Configuración y respaldos", key="settings_expander"):
        tab_template, tab_approvals, tab_history = st.tabs(["Catálogo y precios", "Equivalencias", "Historial"])
        with tab_template:
            st.write("**Actualizar el catálogo y el formato del portal WEB**")
            st.caption("Usa la plantilla del proveedor con su hoja DatosValidacion. Se conservan sus precios, empaques y formato. Las cantidades de esa plantilla no se usan como reposición.")
            replacement = st.file_uploader("Nueva plantilla WEB", type=["xlsx"], key="new_template", max_upload_size=25)
            save_col, reset_col = st.columns(2)
            if save_col.button("Guardar nueva plantilla", disabled=replacement is None, key="save_template", width="stretch"):
                try:
                    memory.save_template(replacement.getvalue(), replacement.name)
                    clear_result_cache()
                    st.session_state["web_flash"] = "Catálogo WEB actualizado. El pedido se calculará con la nueva plantilla."
                    st.rerun()
                except (ReportError, OSError, sqlite3.Error) as exc:
                    st.error(f"No se pudo guardar la plantilla: {exc}")
            if reset_col.button("Usar catálogo WEB integrado", key="reset_template", width="stretch"):
                try:
                    memory.reset_template()
                    clear_result_cache()
                    st.session_state["web_flash"] = "Catálogo WEB integrado restaurado. Tus equivalencias e historial se mantienen."
                    st.rerun()
                except (ReportError, OSError, sqlite3.Error) as exc:
                    st.error(f"No se pudo restaurar el catálogo: {exc}")
            st.divider()
            st.write("**Actualizar el catálogo y los costos de A2**")
            st.caption("Carga el inventario A2 en .xlsx, hasta 25 MB. Se correlacionan sus códigos, descripciones y costos. Los productos completados con valor de A2 toman el costo vigente; los precios de la plantilla WEB se conservan.")
            internal_upload = st.file_uploader("Nuevo inventario A2", type=["xlsx"], key="new_internal_catalog", max_upload_size=25)
            internal_save, internal_reset = st.columns(2)
            if internal_save.button("Guardar inventario A2", disabled=internal_upload is None, key="save_internal_catalog", width="stretch"):
                try:
                    memory.save_internal_catalog(internal_upload.getvalue(), internal_upload.name)
                    clear_result_cache()
                    st.session_state["web_flash"] = "Catálogo y costos A2 actualizados. La comparación y la valoración se volverán a calcular."
                    st.rerun()
                except (ReportError, OSError, sqlite3.Error, ValueError) as exc:
                    st.error(f"No se pudo guardar el inventario A2: {exc}")
            if internal_reset.button("Usar inventario A2 integrado", key="reset_internal_catalog", width="stretch"):
                try:
                    memory.reset_internal_catalog()
                    clear_result_cache()
                    st.session_state["web_flash"] = "Catálogo y costos A2 integrados restaurados. La plantilla WEB, las equivalencias y el historial se conservan."
                    st.rerun()
                except (ReportError, OSError, sqlite3.Error, ValueError) as exc:
                    st.error(f"No se pudo restaurar el inventario A2: {exc}")
            completed = memory.supplemental_products()
            if completed:
                st.divider()
                st.write("**Productos completados**")
                state_labels = {"ACTIVO": "Disponible", "YA_EN_PORTAL": "Ya incluido en la plantilla WEB",
                                "IDENTIDAD_INTERNA_CAMBIO": "Revisar identidad A2", "PRECIO_A2_PENDIENTE": "Revisar costo A2",
                                "CODIGO_INTERNO_AMBIGUO": "Código A2 ambiguo", "NO_EXISTE_EN_INTERNO": "No está en el catálogo A2 activo"}
                st.dataframe([{"Código": p["codigo"], "Descripción": p["descripcion"], "Empaque": p["empaque"],
                               "Valor unitario": p.get("precio_unitario"),
                               "Fuente del valor": {"A2": "Catálogo A2", "MANUAL": "Valor manual", "PORTAL": "Plantilla WEB"}.get(p.get("fuente_precio"), "Por comprobar"),
                               "Estado": state_labels.get(p.get("estado"), p.get("estado", ""))} for p in completed],
                             hide_index=True, width="stretch")
                by_code = {p["codigo"]: p for p in completed}
                remove_product = st.selectbox("Retirar un producto completado", [""] + list(by_code),
                    format_func=lambda code: "Selecciona un producto" if not code else code + " · " + by_code[code]["descripcion"],
                    key="remove_supplemental")
                if st.button("Retirar registro completado", disabled=not remove_product, key="delete_supplemental"):
                    try:
                        memory.delete_supplemental_product(remove_product)
                        clear_result_cache()
                        st.session_state["web_flash"] = "Registro retirado. El catálogo A2 y el historial se conservan."
                        st.rerun()
                    except (ReportError, OSError, sqlite3.Error, ValueError) as exc:
                        st.error(f"No se pudo retirar el registro: {exc}")
        with tab_approvals:
            st.caption(f"{len(decisions)} equivalencias confirmadas guardadas en esta computadora. Las coincidencias automáticas no son aprobaciones tuyas.")
            st.download_button("Descargar respaldo de equivalencias", decision_file(decisions), "equivalencias_WEB.json", "application/json", key="backup_decisions")
            restored = st.file_uploader("Importar un respaldo de equivalencias", type=["json"], key="restore_decisions", max_upload_size=3)
            if st.button("Importar y guardar", disabled=restored is None, key="import_decisions"):
                try:
                    memory.save_decisions(read_decisions(restored.getvalue()))
                    clear_result_cache()
                    st.session_state["web_flash"] = "Respaldo importado. Las equivalencias se volverán a comprobar con el catálogo activo."
                    st.rerun()
                except (ReportError, OSError, sqlite3.Error) as exc:
                    st.error(f"No se pudo importar el respaldo: {exc}")
            if decisions:
                def rule_label(key):
                    if not key:
                        return "Selecciona una equivalencia"
                    d = decisions[key]
                    return f"{d.get('source_code', key[:12])} → {d['target']}"
                remove = st.selectbox("Retirar una equivalencia guardada", [""] + list(decisions), format_func=rule_label, key="remove_rule")
                if remove:
                    st.caption(decisions[remove].get("source_description", ""))
                if st.button("Retirar equivalencia seleccionada", disabled=not remove, key="remove_rule_button"):
                    try:
                        memory.delete_approval(remove)
                        clear_result_cache()
                        st.session_state["web_flash"] = "Equivalencia retirada. El historial se conserva."
                        st.rerun()
                    except (ReportError, OSError, sqlite3.Error) as exc:
                        st.error(f"No se pudo retirar la equivalencia: {exc}")
        with tab_history:
            try:
                history = memory.history()
                if history:
                    st.dataframe([{"Archivo": h.get("Archivo"), "Fecha (UTC)": h.get("Fecha UTC"),
                                   "Renglones": h.get("lineas", 0), "Listos": h.get("listos_validacion_local", 0),
                                   "Por revisar": h.get("bloqueados_carga", 0)} for h in history],
                                 hide_index=True, width="stretch")
                    st.caption("Últimos 30 archivos procesados. Este historial no reutiliza las cantidades ni confirma cargas en el portal.")
                else:
                    st.caption("Aquí aparecerá un resumen de los archivos que proceses.")
            except (OSError, sqlite3.Error, ValueError) as exc:
                st.error(f"No se pudo leer el historial: {exc}")
        st.caption(f"Versión {VERSION} · Datos guardados en esta computadora")



def _ui_resolve(st, memory: LocalMemory, template: Template, blocked: list[Match]) -> None:
    pending_label = "1 renglón pendiente" if len(blocked) == 1 else f"{len(blocked)} renglones pendientes"
    with st.expander(f"Completar {pending_label}", expanded=len(blocked) == 1):
        if len(blocked) > 1:
            st.dataframe([{"Código origen": m.source.code, "Descripción origen": m.source.description,
                           "Cantidad original": m.source.quantity,
                           "Qué completar": " ".join(_ui_reason(r) for r in m.load_reasons)} for m in blocked],
                         hide_index=True, width="stretch")
            selected_i = st.selectbox("Renglón por completar", list(range(len(blocked))),
                format_func=lambda i: f"{blocked[i].source.code} · {blocked[i].source.description} · fila {blocked[i].source.row}",
                key="pending_selection")
            m = blocked[selected_i]
        else:
            m = blocked[0]
        structural = {"CODIGO_DESTINO_REPETIDO_NO_SE_HAN_SUMADO_CANTIDADES", "CANTIDAD_CERO_NO_SE_ENVIA_AL_PROVEEDOR", "FALTA_CODIGO_ORIGEN"}
        structural_reasons = [reason for reason in m.load_reasons if reason in structural]
        if structural_reasons or money(m.source.quantity) <= 0:
            st.info(" ".join(_ui_reason(reason) for reason in structural_reasons) or "Corrige la cantidad original antes de continuar.")
            st.caption("Corrige el reporte original y vuelve a cargarlo. Completar un empaque no resuelve este bloqueo.")
            return
        internal = memory.internal_catalog()
        identified = lookup_internal_product(m.source, internal)
        if m.product is None and identified.get("encontrado"):
            _ui_complete_product(st, memory, m, identified)
            return
        unresolvable = {"CODIGO_DESTINO_REPETIDO_NO_SE_HAN_SUMADO_CANTIDADES", "CANTIDAD_CERO_NO_SE_ENVIA_AL_PROVEEDOR",
                        "PRECIO_INVALIDO", "EMPAQUE_AUSENTE_O_NO_ENTERO_POSITIVO", "FALTA_CODIGO_ORIGEN", "FALTA_DESCRIPCION_ORIGEN"}
        reasons = list(dict.fromkeys(_ui_reason(r) for r in m.load_reasons))
        st.caption(" ".join(reasons))
        if not any(r not in unresolvable for r in m.critical):
            st.info("Corrige este dato en la reposición original o en el catálogo correspondiente y vuelve a cargar el archivo.")
            return
        if not m.product and not m.suggestions and identified.get("estado") != "AMBIGUO_CODIGO":
            st.info("No se encontró este código en los catálogos activos. Actualiza el inventario A2 o la plantilla WEB con la referencia correcta.")
            return
        st.markdown("**Revisar una equivalencia**")
        st.caption("Selecciona otra referencia solo cuando hayas confirmado que corresponde al mismo producto.")
        left, right = st.columns(2)
        with left:
            st.markdown("**Producto del reporte**")
            st.write(m.source.code)
            st.write(m.source.description)
        with right:
            st.markdown("**Referencia encontrada**")
            st.write(m.product.code if m.product else "Sin equivalencia confirmada")
            if m.product:
                st.write(m.product.description)
        all_codes = [p.code for p in template.catalog]
        candidates = list(dict.fromkeys(([m.product.code] if m.product else []) + m.suggestions))
        options = [""] + [c for c in candidates if c in all_codes] + [c for c in all_codes if c not in candidates]
        def code_label(code):
            return "Selecciona el código que comprobaste" if not code else code + " · " + template.by_code[code_key(code)][0].description
        target = st.selectbox("Código confirmado", options, format_func=code_label, key="target_" + m.source.key)
        if target:
            product = template.by_code[code_key(target)][0]
            reason = st.text_input("Cómo comprobaste la equivalencia", placeholder="Ej.: confirmación del proveedor", key="reason_" + m.source.key)
            accept = st.checkbox("Comprobé que ambos códigos corresponden al mismo producto y quiero guardar la equivalencia.", key="accept_" + m.source.key + target)
            if st.button("Confirmar equivalencia", disabled=not (accept and reason.strip()), type="primary", key="confirm_" + m.source.key):
                try:
                    memory.approve(m.source, product, reason.strip())
                    st.session_state["web_flash"] = "Equivalencia guardada. El pedido fue recalculado."
                    st.rerun()
                except (ReportError, OSError, sqlite3.Error) as exc:
                    st.error(f"No se pudo guardar la equivalencia: {exc}")



def _ui_results(st, memory: LocalMemory, template: Template, template_data: bytes,
                source_data: bytes, source_name: str, decisions: dict, matches: list[Match], notes: list[str], summary: dict) -> None:
    blocked = [m for m in matches if not m.loadable]
    valid = [m for m in matches if m.loadable]
    ready_label = "1 renglón listo" if len(valid) == 1 else f"{len(valid)} renglones listos"
    pending_label = "1 renglón pendiente" if len(blocked) == 1 else f"{len(blocked)} renglones pendientes"
    cost_rows, costs_by_match = [], {}
    try:
        cost_rows = cost_audit_rows(matches, memory.internal_catalog())
        supplemental_values = {code_key(p['codigo']): p for p in memory.supplemental_products() if p.get('estado') == 'ACTIVO'}
        for row in cost_rows:
            completed = supplemental_values.get(code_key(row.get('codigo_web', '')))
            row['fuente_valor_salida'] = ('Catálogo A2' if completed.get('fuente_precio') == 'A2' else 'Valor manual') if completed else ('Plantilla WEB' if row.get('codigo_web') else 'Por completar')
            row['valor_unitario_salida'] = row.pop('precio_portal', None)
            row['empaque_salida'] = row.pop('empaque_portal', None)
            row['importe_pedido_salida'] = row.pop('total_precio_portal', None)
        if len(cost_rows) != len(matches):
            raise ReportError("La correlación de costos no contiene todos los renglones de la reposición.")
        costs_by_match = {id(match): row for match, row in zip(matches, cost_rows)}
    except (ReportError, OSError, sqlite3.Error, ValueError) as exc:
        cost_rows = []
        st.warning(f"No se pudieron consultar los costos A2: {exc}. Los valores del pedido ya preparado se conservan.")
    _ui_heading(st, "02", "Revisa tu reposición", "Las cantidades se ajustan al siguiente empaque completo. El original permanece en la revisión.")
    cols = st.columns(4)
    for col, label, count in zip(cols, ["Renglones", "Listos", "Por completar", "Ajustados por empaque"],
                                  [len(matches), len(valid), len(blocked), sum(m.pack_issue for m in matches)]):
        col.metric(label, _ui_format(count))
    if blocked:
        st.info(f"{ready_label} y {pending_label}. Completa el dato pendiente o descarga los renglones listos.")
    else:
        st.success("Todos los renglones tienen código identificado, cantidad y empaque válidos.")
    if notes:
        with st.expander(f"Observaciones del archivo · {len(notes)}"):
            for note in notes:
                st.warning(note)
    descriptions = [m for m in matches if m.product and m.loadable and
                    code_key(m.source.code) == code_key(m.product.code) and
                    desc_key(m.source.description) != desc_key(m.product.description)]
    if descriptions:
        with st.expander(f"Información de descripciones · {len(descriptions)} actualizadas"):
            st.caption("El código identifica el producto. Se usa la descripción del catálogo; estas diferencias no bloquean el pedido.")
            st.dataframe([{"Código": m.output_code, "Descripción original": m.source.description,
                           "Descripción de salida": m.output_description} for m in descriptions],
                         hide_index=True, width="stretch", height=min(320, 38 + len(descriptions) * 35))
    filter_col, query_col = st.columns([1.4, 1])
    with filter_col:
        selected_filter = st.radio("Mostrar", ["Todos", "Listos", "Pendientes", "Ajustados"], horizontal=True, key="result_filter")
    with query_col:
        query = st.text_input("Buscar producto", placeholder="Código o descripción", key="result_search")
    tokens = desc_key(query).split()
    selected = [m for m in matches if (selected_filter == "Todos" or
                selected_filter == "Listos" and m.loadable or
                selected_filter == "Pendientes" and not m.loadable or
                selected_filter == "Ajustados" and m.pack_issue) and
                all(t in desc_key(m.source.code + " " + m.source.description + " " + m.output_code + " " + m.output_description) for t in tokens)]
    preview = [{"Estado": "Por revisar" if not m.loadable else "Ajustado" if m.pack_issue else "Listo",
                "Código origen": m.source.code,
                "Código de salida": m.product.code if m.product else "Por completar", "Descripción": m.output_description,
                "Empaque": m.product.pack if m.product else None,
                "Original": m.source.quantity, "Pedido": m.output_quantity,
                "Añadidas": float(m.added_units),
                "Costo unitario A2": costs_by_match.get(id(m), {}).get("costo_a2"),
                "Valor unitario": m.product.price if m.product else None,
                "Total pedido": float(money(m.output_quantity) * money(m.product.price)) if m.product else None} for m in selected]
    if preview:
        st.dataframe(preview, hide_index=True, width="stretch", height=min(440, 38 + len(preview) * 35),
                     column_config={"Costo unitario A2": st.column_config.NumberColumn(format="%.2f"),
                                    "Valor unitario": st.column_config.NumberColumn(format="%.2f"),
                                    "Total pedido": st.column_config.NumberColumn(format="%.2f")})
        st.caption(f"{len(preview)} de {len(matches)} renglones · Cantidades en unidades. Los importes de pendientes son provisionales.")
        st.caption("Valores del pedido: datos de la plantilla WEB y registros completados. El costo A2 se muestra por separado.")
    else:
        st.info("No hay productos con ese filtro o búsqueda.")
    if blocked:
        _ui_resolve(st, memory, template, blocked)
    if valid:
        ready_summary = summarize(valid)
        st.markdown(f"**Pedido listo: {_ui_format(ready_summary['unidades_pedido'])} unidades · Importe pedido {_ui_format(ready_summary['importe_con_precios_conocidos'], decimals=2)}**")
        st.caption("Importe de los renglones listos. No agrega impuestos, flete ni descuentos.")
    if cost_rows:
        _ui_costs(st, cost_rows, source_name)
    _ui_heading(st, "03", "Descarga el formato WEB", "Conserva las seis columnas y las fórmulas, con los datos de la plantilla y los registros completados.")
    signature = hashlib.sha256(VERSION.encode() + source_data + template_data + decision_file(decisions) +
                               json.dumps(audit_rows(matches), ensure_ascii=False, sort_keys=True).encode()).hexdigest()
    # El aprendizaje cambia método/índice de auditoría, pero no el pedido aceptado.
    # La aceptación solo se reinicia si cambian entrada, plantilla o decisiones.
    partial_signature = hashlib.sha256(VERSION.encode() + source_data + template_data + decision_file(decisions)).hexdigest()
    stem = re.sub(r"[^A-Za-z0-9_-]+", "_", Path(source_name).stem).strip("_") or "REPOSICION"
    accept_partial = not blocked
    if blocked:
        accept_partial = st.checkbox(f"Descargar {ready_label} y dejar fuera {pending_label}.", key="partial_" + partial_signature)
    ready = None
    if valid and accept_partial:
        cache = st.session_state.get("web_valid_v43")
        if not cache or cache[0] != signature:
            try:
                with st.spinner("Verificando el archivo de salida…"):
                    result = bundle_result(template, matches, stem, only_valid=True)
                st.session_state["web_valid_v43"] = (signature, result)
            except (ReportError, OSError, ValueError) as exc:
                st.error(f"No se pudo preparar la descarga: {exc}")
        ready = st.session_state.get("web_valid_v43")
        if ready and ready[0] == signature:
            output, audit, zipped, filename = ready[1]
            row_label = "1 renglón" if len(valid) == 1 else f"{len(valid)} renglones"
            label = f"Descargar WEB parcial · {row_label}" if blocked else "Descargar formato WEB"
            st.download_button(label, output, filename, "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                               type="primary", width="stretch", key="download_ready")
            if blocked:
                st.caption(f"Esta descarga excluye {pending_label}. Consulta el archivo de revisión para ver el detalle.")
            st.caption("Comprobado con el catálogo de salida. La aceptación final se verifica al cargarlo en el portal.")
    elif not valid:
        st.info("Resuelve los renglones pendientes para generar un archivo de carga.")
    else:
        st.caption("Marca la casilla para preparar la descarga parcial o resuelve primero los pendientes.")
    with st.expander("Revisión completa y otras descargas"):
        review_selected = valid if ready and ready[0] == signature and accept_partial else []
        st.download_button("Descargar revisión de todos los renglones", csv_bytes(audit_rows(matches, review_selected)),
                           "REVISION_" + stem + ".csv", "text/csv", key="download_audit")
        st.download_button("Descargar ajustes de empaque", csv_bytes(packaging_rows(matches)),
                           "EMPAQUES_" + stem + ".csv", "text/csv", key="download_packs")
        if ready and ready[0] == signature and accept_partial:
            st.download_button("Descargar carga + revisión en ZIP", ready[1][2],
                               "PEDIDO_WEB_" + stem + ".zip", "application/zip", key="download_zip")
        if blocked:
            st.caption("El Excel completo de revisión conserva también los pendientes y no está listo para cargar en el portal.")
            if st.button("Preparar Excel completo para revisión", key="prepare_review"):
                try:
                    with st.spinner("Preparando copia completa de revisión…"):
                        st.session_state["web_review_v43"] = (signature, bundle_result(template, matches, stem))
                except (ReportError, OSError, ValueError) as exc:
                    st.error(f"No se pudo preparar la revisión: {exc}")
            review = st.session_state.get("web_review_v43")
            if review and review[0] == signature:
                st.download_button("Descargar COMPLETO PARA REVISAR", review[1][0], review[1][3],
                                   "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet", key="download_review_full")



def _ui_complete_product(st, memory: LocalMemory, match: Match, product: dict[str, Any]) -> None:
    st.markdown("**Completa el empaque de este producto**")
    st.write(f"**{product['codigo_a2']}** · {product['descripcion_a2']}")
    st.caption("El producto ya está identificado en A2. Conservaremos este mismo código y su descripción en el archivo de salida.")
    cost = product.get("costo_a2")
    has_cost = cost is not None and money(cost) > 0
    if has_cost:
        st.markdown(f"Valor unitario del catálogo A2: **{_ui_format(cost, decimals=2)}**")
    elif cost is not None:
        st.caption("El costo A2 está en cero. Introduce un valor unitario confirmado para completar este producto.")
    else:
        st.caption("No hay un costo A2 válido. Introduce un valor unitario confirmado para completar este producto.")
    saved = next((p for p in memory.supplemental_products() if code_key(p["codigo"]) == code_key(product["codigo_a2"])), None)
    initial_pack = int(saved["empaque"]) if saved and valid_pack(saved.get("empaque")) else 0
    pack = st.number_input("Unidades por empaque", min_value=0, value=initial_pack, step=1,
                           help="Escribe cuántas unidades trae el empaque confirmado. Cero significa que aún falta completar este dato.",
                           key="supplement_pack_" + match.source.key)
    manual = st.checkbox("Usar otro valor unitario (opcional)", key="supplement_manual_" + match.source.key) if has_cost else True
    price = None
    if manual:
        price = st.number_input("Valor unitario confirmado", min_value=0.0, value=float(cost) if has_cost else 0.0,
                                step=0.01, format="%.2f", key="supplement_price_" + match.source.key)
    valid_value = has_cost if price is None else money(price) > 0
    if valid_pack(pack):
        amount = quantity_for_pack(match.source.quantity, pack)
        st.caption(f"Con este empaque, {_ui_format(match.source.quantity)} unidades solicitadas pasan a {_ui_format(amount)} unidades en el pedido.")
    if st.button("Guardar empaque y recalcular", disabled=not (valid_pack(pack) and valid_value),
                 type="primary", key="save_supplement_" + match.source.key):
        try:
            memory.save_supplemental_product(product["codigo_a2"], pack, price=price)
            for key in list(st.session_state):
                if key.startswith(("web_process_", "web_valid_", "web_review_")):
                    st.session_state.pop(key, None)
            st.session_state["web_flash"] = f"{product['codigo_a2']}: empaque guardado y pedido recalculado."
            st.rerun()
        except (ReportError, OSError, sqlite3.Error, ValueError) as exc:
            st.error(f"No se pudo completar el producto: {exc}")
    st.caption("El archivo conserva sus seis columnas. El empaque queda guardado para las siguientes reposiciones.")



def run_ui() -> None:
    import streamlit as st
    global _internal_snapshot
    # Mantiene la comparación entre reruns; ambas fuentes forman la clave.
    _internal_snapshot = st.cache_data(show_spinner=False, max_entries=4)(_internal_snapshot.__wrapped__)
    from html import escape as safe
    st.set_page_config(page_title="Reposición WEB · Makropetrol", page_icon="📦", layout="wide", initial_sidebar_state="collapsed")
    _ui_styles(st)
    st.markdown(f'<div class="web-masthead"><div class="web-brand"><span class="web-symbol">m.</span>makropetrol</div>'
                f'<div class="web-version">REPOSICIÓN WEB &nbsp; / &nbsp; {safe(VERSION)}</div></div>', unsafe_allow_html=True)
    st.markdown('<div class="web-hero"><div><div class="web-eyebrow">Menos pasos. Más claridad.</div>'
                '<h1>Tu reposición,<br>lista para WEB.</h1>'
                '<p>Sube tu reporte. El catálogo, los empaques y el formato del proveedor ya están integrados.</p></div>'
                '<div class="web-track"><div class="web-step"><span>01</span>Carga el reporte</div>'
                '<div class="web-step"><span>02</span>Revisa el resultado</div>'
                '<div class="web-step"><span>03</span>Descarga tu pedido</div></div></div>', unsafe_allow_html=True)
    if st.session_state.get("web_flash"):
        st.success(st.session_state.pop("web_flash"))
    try:
        memory = LocalMemory()
        decisions = memory.decisions()
    except (OSError, sqlite3.Error, ReportError, ValueError) as exc:
        st.error(f"No se pudo abrir la información guardada en esta computadora: {exc}")
        st.info("Comprueba que la carpeta de datos tenga permisos de escritura y que ninguna copia de la aplicación esté bloqueando su acceso.")
        return
    try:
        portal_data, template_name = memory.active_template()
        template_data = memory.order_template_data(portal_data)
        template = load_template(template_data)
    except (ReportError, OSError, sqlite3.Error) as exc:
        st.error(f"No se pudo leer el catálogo activo: {exc}")
        _ui_settings(st, memory, decisions, None)
        return
    if hasattr(memory, "template_notice"):
        notice = memory.template_notice()
        if notice:
            st.info(notice)
    _ui_heading(st, "01", "Carga la reposición original", "Usa el reporte con Código, Descripción y A pedir. Si una descripción está vacía, se completa por código. Usa el reporte original en formato .xlsx.")
    uploaded = st.file_uploader("Selecciona o arrastra tu reporte de reposición", type=["xlsx"], key="source_upload", max_upload_size=25,
                                help="Carga el reporte original de A2/NEXUS. El catálogo WEB ya está integrado; un pedido WEB generado no es una reposición original.")
    st.caption(f"Catálogo activo: {template_name} · {_ui_format(len(template.catalog))} referencias · Empaques automáticos")
    if uploaded is None:
        st.markdown('<div class="web-example"><div><small>Así se completa un empaque de 12</small>'
                    '<strong>125 unidades <span class="web-arrow">→</span> 132 unidades</strong></div>'
                    '<div class="web-example-note">Se piden 11 empaques completos. La revisión conserva las 125 unidades originales y muestra las 7 añadidas.</div></div>', unsafe_allow_html=True)
    else:
        source_data = uploaded.getvalue()
        try:
            documentary = memory.documentary_index()
            process_key = hashlib.sha256(VERSION.encode() + source_data + template_data + decision_file(decisions) +
                                         json.dumps(documentary, ensure_ascii=False, sort_keys=True).encode() +
                                         internal_payload(memory.internal_catalog())).hexdigest()
            cached = st.session_state.get("web_process_v43")
            if not cached or cached[0] != process_key:
                with st.spinner("Leyendo el reporte y comprobando productos…"):
                    matches, notes, summary = prepare_result(source_data, template_data, decisions, documentary)
                st.session_state["web_process_v43"] = (process_key, matches, notes, summary)
                try:
                    memory.learn_documentary(matches)
                    log_key = hashlib.sha256(VERSION.encode() + source_data + template_data + decision_file(decisions)).hexdigest()
                    memory.log(log_key, uploaded.name, summary)
                except (OSError, sqlite3.Error, ReportError) as exc:
                    st.warning(f"El cálculo está disponible, pero no se pudo actualizar la memoria local: {exc}")
            else:
                _, matches, notes, summary = cached
            _ui_results(st, memory, template, template_data, source_data, uploaded.name, decisions, matches, notes, summary)
        except (ReportError, OSError, sqlite3.Error, ValueError) as exc:
            st.error(f"Revisa el archivo para continuar: {exc}")
            st.info("Corrige la fila indicada y vuelve a cargar la reposición original. La aplicación no convierte datos inválidos en cero.")
    st.markdown("<div style='height:.6rem'></div>", unsafe_allow_html=True)
    _ui_settings(st, memory, decisions, template, template_name)
    st.markdown('<div class="web-footer"><span>Makropetrol · Reposición WEB</span>'
                '<span>El pedido se descarga para que tú lo cargues en el portal.</span></div>', unsafe_allow_html=True)



if __name__ == "__main__":
    if "--version" in sys.argv:
        print("WEB", VERSION, "EMPAQUES AUTOMÁTICOS ACTIVOS")
        raise SystemExit(0)
    if "--entrada" in sys.argv or "--help" in sys.argv:
        raise SystemExit(cli(sys.argv[1:]))
    try:
        from streamlit.runtime.scriptrunner import get_script_run_ctx
        if get_script_run_ctx(suppress_warning=True) is None:
            from streamlit.web import cli as stcli
            sys.argv = ["streamlit", "run", str(Path(__file__).resolve()),
                        "--server.address=127.0.0.1", "--server.port=8514", "--theme.base=light", "--theme.primaryColor=#153e34", "--browser.gatherUsageStats=false"]
            raise SystemExit(stcli.main())
        run_ui()
    except ModuleNotFoundError as exc:
        if exc.name and exc.name.startswith("streamlit"):
            print('Instala la interfaz: py -3.12 -m pip install "streamlit==1.65.0"')
            print("Luego: py -3.12 -m streamlit run app_web_reposicion_4_3.py")
            raise SystemExit(1)
        raise
